use common::OwnedBytes;
use tantivy_sstable::{Dictionary, MonotonicU64SSTable};

// Generated by upstream tantivy-sstable 0.7.0 with zstd 0.13.3.
#[test]
fn reads_compressed_sstable_from_previous_zstd() {
    let bytes = include_bytes!("fixtures/zstd-0.13.3.sstable");
    assert!(bytes.windows(4).any(|window| window == [0x28, 0xb5, 0x2f, 0xfd]));
    let dictionary = Dictionary::<MonotonicU64SSTable>::from_bytes(OwnedBytes::new(bytes.to_vec()))
        .expect("old compressed index must open");
    for ordinal in [0_u64, 1, 3_333, 9_999] {
        let key = format!("term-{ordinal:05}");
        assert_eq!(dictionary.get(key.as_bytes()).unwrap(), Some(ordinal));
    }
}
